import React, { useState, useEffect } from 'react';
import { Container, Row, Col, Table, Card, CardBody, FormGroup, Label, Input } from 'reactstrap';
import { BASE_URL } from '../../utils/config';

const Dashboard = () => {
  const [bookings, setBookings] = useState([]);
  const [stats, setStats] = useState({ totalRevenue: 0, totalBookings: 0, canceledBookings: 0, cancelRate: 0, topTourList: [] });
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState(null);
  const [startDate, setStartDate] = useState('');
  const [endDate, setEndDate] = useState('');

  useEffect(() => {
    const fetchData = async () => {
      setLoading(true);
      setError(null);
      try {
        const token = localStorage.getItem('token');
        const res = await fetch(`${BASE_URL}/booking/sales/revenue`, {
          headers: {
            'Content-Type': 'application/json',
            Authorization: `Bearer ${token}`,
          },
        });
        const result = await res.json();
        if (!res.ok) {
          setError(result.message || 'Lỗi tải dữ liệu');
          setLoading(false);
          return;
        }
        setBookings(result.data || []);
        setStats(result.stats || {});
      } catch (err) {
        setError('Lỗi kết nối đến server');
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  const filteredBookings = bookings?.filter(item => {
    if (item.status !== 'Đã thanh toán') return false;
    if (!startDate || !endDate) return true;
    const bookingDate = new Date(item.createdAt).getTime();
    const start = new Date(startDate).getTime();
    const end = new Date(endDate).getTime() + 86400000;
    return bookingDate >= start && bookingDate <= end;
  });

  const totalRevenue = filteredBookings?.reduce((acc, item) => acc + (item.totalPrice || 0), 0) || 0;

  return (
    <section>
      <Container>
        <Row>
          <Col lg='12'>
            <h3 className="mb-4">Quản lý doanh thu</h3>
          </Col>

          <Col lg='12' className="mb-4">
            <Card className="p-3 shadow-sm border-0">
              <div className="d-flex align-items-end gap-3 flex-wrap">
                <FormGroup className="mb-0">
                  <Label className="fw-bold">Từ ngày:</Label>
                  <Input type="date" onChange={e => setStartDate(e.target.value)} />
                </FormGroup>
                <FormGroup className="mb-0">
                  <Label className="fw-bold">Đến ngày:</Label>
                  <Input type="date" onChange={e => setEndDate(e.target.value)} />
                </FormGroup>
                <div className="text-muted pb-2">* Hệ thống tự động lọc khi bạn chọn ngày</div>
              </div>
            </Card>
          </Col>

          <Col lg='3' className="mb-4">
            <Card className="bg-primary text-white border-0 shadow-sm">
              <CardBody>
                <h5>Doanh thu (đã lọc)</h5>
                <h4>{totalRevenue.toLocaleString('vi-VN')}đ</h4>
              </CardBody>
            </Card>
          </Col>
          <Col lg='3' className="mb-4">
            <Card className="bg-success text-white border-0 shadow-sm">
              <CardBody>
                <h5>Số đơn hàng</h5>
                <h4>{filteredBookings?.length || 0} đơn</h4>
              </CardBody>
            </Card>
          </Col>
          <Col lg='3' className="mb-4">
            <Card className="bg-warning text-white border-0 shadow-sm">
              <CardBody>
                <h5>Tỷ lệ hủy</h5>
                <h4>{stats.cancelRate || 0}%</h4>
              </CardBody>
            </Card>
          </Col>
          <Col lg='3' className="mb-4">
            <Card className="bg-info text-white border-0 shadow-sm">
              <CardBody>
                <h5>Tour bán chạy</h5>
                <h6>{stats.topTourList?.[0]?.tourName || 'Chưa có'}</h6>
                <small>{stats.topTourList?.[0]?.clients || 0} khách</small>
              </CardBody>
            </Card>
          </Col>
        </Row>

        <Row>
          <Col lg='12'>
            <Table striped responsive className="bg-white rounded shadow-sm">
              <thead>
                <tr>
                  <th>Khách hàng</th>
                  <th>Tên Tour</th>
                  <th>Ngày đặt</th>
                  <th>Tổng tiền</th>
                  <th>Trạng thái</th>
                </tr>
              </thead>
              <tbody>
                {loading && <tr><td colSpan='5'>Đang tải...</td></tr>}
                {!loading && filteredBookings?.length === 0 && (
                  <tr><td colSpan='5'>Không có booking phù hợp.</td></tr>
                )}
                {!loading && filteredBookings?.map(item => (
                  <tr key={item._id}>
                    <td>{item.fullName}</td>
                    <td>{item.tourName}</td>
                    <td>{new Date(item.createdAt).toLocaleDateString('vi-VN')}</td>
                    <td className="fw-bold text-success">{(item.totalPrice || 0).toLocaleString('vi-VN')}đ</td>
                    <td>{item.status}</td>
                  </tr>
                ))}
              </tbody>
            </Table>
          </Col>
        </Row>
      </Container>
    </section>
  );
};

export default Dashboard;
